function tornaInici() {
	$("html, body").animate({scrollTop:20}, "slow");
	return false;
}

function mostrarTaset(codi, tipus) {
	if (!$('#veure_tastet_'+codi)[0]) {
		$.ajax({
			url: "https://www.prisma.cat/ajax/mostrar_tastet.php?dispositiu=" + dispositiu + "&codi=" + codi+"&tipus=" + tipus,
			cache: !1,
			type: "GET",
			success: function(tastet) {
				$("#contingut_curs").append(tastet);

				//Mostrar el video de la presentacio del curs quan cliques la caratula
				var video  = $('#veure_tastet_'+codi+" .video-responsive");
				video.on("click", function(){
					var obj = $(this);
					$(this).find('iframe')[0].src=$(this).find('iframe')[0].src.replace("autoplay=0", "autoplay=1");
					setTimeout(function(){
						obj.find('button').hide();
						obj.find('img').hide();
					},500);
				});

				//Pausar el video quan surts del modal de veure un tastet
				$('#veure_tastet_'+codi).on('hide.bs.modal', function (e) {
					if ($(this).find('iframe')[0]) {
						var src= $(this).find('iframe')[0].src;
						$(this).find('iframe')[0].src = src;
						$(this).find('iframe')[0].src = src.replace("autoplay=1", "autoplay=0");
						$(this).find('img').show();
						$(this).find('button').show();
					}
				});

				//Pausar el video de presentacioq quan s'obre un modal
				$('#veure_tastet_'+codi).on('show.bs.modal ', function (e) {
					if ($('#video-presentacio iframe')[0]) {
					  var src= $('#video-presentacio iframe')[0].src;
					  $('#video-presentacio iframe')[0].src = src;
					  $('#video-presentacio iframe')[0].src = src.replace("autoplay=1", "autoplay=0");
					  $('#video-presentacio').find('img').show();
					  $('#video-presentacio').find('button').show();
				  }
				});
				$('#veure_tastet_'+codi).modal('show');
			}
		})
	}
	else {
		$('#veure_tastet_'+codi).modal('show');
	}
}

function scrollEventSticky() {
	var stickyBody = $('.sticky-body');
   var heightStickySideBar = $('.sticky-sidebar').css('height');
	if (screenWitdh > 992) {
		$('.sticky-sidebar').css("height", stickyBody.css('height'));
		console.log('sticky-sidebar height '+stickyBody.css('height'));
		if ((document.body.scrollTop > 0 || document.documentElement.scrollTop > 0)) {
			var mida_top = 0;
			$('#mes_informacio').css("padding-top", mida_top);
			console.log('scrolltop > 0');
		}
		else {
			console.log('scrolltop < 0');
			$('#mes_informacio').css("padding-top", "0");
			$('.sticky-sidebar').css("height", stickyBody.css('height'));
			console.log('sticky-sidebar height '+stickyBody.css('height'));
		}
	}
}

//Función que es crida quan es clica el botó de copiar
function copiarAlPortapapeles(){
	var aux = document.createElement("input");
	aux.setAttribute("value", $('#textCopiar').val());
	// S'afageix el nou camp a la pàgina
	document.body.appendChild(aux);
	// Se sel·lecciona el contingut del camp
	aux.select();
	try {
		var res = document.execCommand('copy'); //Intento copiar en el porta-retalls
		if (res) exit();
		else fracas();

		mostrarAlerta();
	}
	catch(ex) {
		excepcio();
	}

	// Elimina el campo de la página
	document.body.removeChild(aux);

	function exit() {
		divAlerta = document.getElementById('alerta');
		divAlerta.innerText = 'Text copiat al porta-retalls';
		divAlerta.classList.add('alert-success');
	}

	function fracas() {
		divAlerta = document.getElementById('alerta');
		divAlerta.innerText = 'Ha fallat al porta-retalls';
		divAlerta.classList.add('alert-warning');
	}

	function excepcio() {
		divAlerta = document.getElementById('alerta');
		divAlerta.innerText = "S'ha produit un error al porta-retalls";
		divAlerta.classList.add('alert-danger');
	}

	function mostrarAlerta() {
		divAlerta = document.getElementById('alerta');
		divAlerta.classList.remove('invisible');
		divAlerta.classList.add('visible');
		setTimeout(amagarAlerta, 1500);
	}

	function amagarAlerta() {
		divAlerta = document.getElementById('alerta');
		divAlerta.innerText = '';
		divAlerta.classList.remove('alert-success', 'alert-warning', 'alert-danger', 'visible');
		divAlerta.classList.add('invisible');
	}
}

/* Validacions */

function mostrarError(id_error, error) {
	$("#" + id_error).html(error);
	$("#" + id_error).addClass("erroni text-center text-white")
}

function eliminarError(id_error) {
	$("#" + id_error).html("");
	$("#" + id_error).removeClass("erroni")
}

function validacioCampBuit(id, id_error) {
	var error = "";
	if ($("#" + id).val().length == 0) {
		error = "Camp obligatori";
		mostrarError(id_error, error)
	} else {
		eliminarError(id_error)
	}
	return error
}

function validacioNom(id, id_error) {
	var error = validacioCampBuit(id, id_error);
	return error
}

function validacioCognoms(id, id_error) {
	var error = validacioCampBuit(id, id_error);
	return error
}

function validacioEmail(id, id_error) {
	var email = $('#'+id).val();
	var error = validacioCampBuit(id, id_error);
	if (email.length != 0) {
		var tfld_email = $.trim(email);
		var emailFilter = /^([\w-\.]+@([\w-]+\.)+[\w-]{2,4})?$/;
		var illegalChars = /[\(\)\<\>\,\;\:\\\"\[\]]/;
		if (!emailFilter.test(tfld_email)) {
			error = "Correu electr\u00F2nic no v\u00E0lid";
			mostrarError(id_error, error)
		} else if (email.match(illegalChars)) {
			error = "Car\u0E0cters no permesos";
			mostrarError(id_error, error)
		}
		if (error == "") {
			eliminarError(id_error)
		}
	}
	return error
}

function validacioTelefon(id, id_error) {
	var telf = $('#'+id).val();
	var error = validacioCampBuit(id, id_error);
	if (telf.length != 0) {
		var stripped = telf.replace(/[\(\)\.\-\ ]/g, '');
		if (!(stripped.length == 9)) {
			error = "Llargada incorrecta";
			mostrarError(id_error, error)
		} else if (isNaN(stripped)) {
			error = "Car\u00E0cters no permesos";
			mostrarError(id_error, error)
		} else {
			eliminarError(id_error)
		}
	}
	return error
}

function validacioFormulariLlista() {
	var comprovacio = '';
	var validNomNoBuit = validacioNom("nom", "nom_erroni");
	var validCogNoBuit = validacioCognoms("cog", "cog_erroni");
	var validEmailNoBuit = validacioEmail("email", "correu_erroni");
	var validTel = validacioTelefon("telf", "telf_erroni");
	if (validNomNoBuit.length != 0) comprovacio += "<li>Nom</li>";
	if (validCogNoBuit.length != 0) comprovacio += "<li>Cognoms</li>";
	if (validEmailNoBuit.length != 0) comprovacio += "<li>Adreça electrònica</li>";
	if (validTel.length != 0) comprovacio += "<li>Telèfon</li>";
	if (comprovacio == '') {
		// $('#modalLlistaBody').fadeOut();
		$('#modalLlistaBody .formulari-llista-espera').hide();
		$('#modalLlista #loading-wrapper').show();
		$('#modalLlista .modal-footer').hide();
		// mostrarLoadingLlistes();
		enviarConsultaLlista();
	}
	return (comprovacio == "")
}

function enviarConsultaLlista() {
	var edicio = $("#edicio").val();
	var email = $("#email").val();
	var telf = $("#telf").val();
	var comprovaSpam = $("#comprovaSpam").val();
	var h1 = $("h1").html();
	var nom = $("#nom").val();
	var cog = $("#cog").val();
	var curs = $("#curs").val();
	var apartats = [
		['edicio', edicio],
		['email', email],
		['telf', telf],
		['nom', nom],
		['cog', cog],
		['titol', h1],
		['curs', curs],
		['comprovaSpam', comprovaSpam]
	];

	$.ajax({
		url: "https://www.prisma.cat/ajax/enviarLlistaEspera.php?apartats=" + JSON.stringify(apartats) + "&length=" + apartats.length,
		cache: !1,
		type: "GET",
		success: function(message) {
			var missatge;
			if (message == "ok") {
				missatge = "<p>La teva sol·licitud s'ha enviat correctament.</p>";
				missatge += "<p>Quan s'alliberi una plaça del curs <span class='font-weight-bold consulta'>"+h1+"</span> ens posarem en contacte amb tu a través del correu <span class='font-weight-bold consulta'>"+email+"</span> i/o del telèfon <span class='font-weight-bold consulta'>"+telf+"</span>.</p>";
				missatge += "<p>Gràcies per confiar en PrisMa!</p>";
			} else {
				missatge = message;
			}
			$('#modalSuccessLlistaBody').html(missatge);
			$('#modalLlista #loading-wrapper').hide();
			$('#modalSuccessLlistaBody').show();

			$('#modalLlista').on('hidden.bs.modal', function (e) {
				$('#modalLlista #loading-wrapper').hide();
				$('#modalSuccessLlistaBody').hide();
				$('#modalLlista .formulari-llista-espera').show();
				$('#modalLlista .modal-footer').show();
				$("#email").val('');
				$("#telf").val('');
				$("#nom").val('');
				$("#cog").val('');
				$("#modalLlista label").removeClass('active');
			});
		}
	})
}

